	[1111]={ type=1, hero_id={1111}, name="", talk_part={
		[1]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Hello... I am Kymia Albert. You may call me Kymia.", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3,4}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[3]={ next_id={5}, type=1, msg="It's our first meeting. I hope we can get along pleasantly.", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=1, msg="Hello, nice to meet you, Kymia.", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Hmm? So this is how it should be said?", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=1, msg="Hmm—?", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="So when meeting for the first time, such words are required?", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10,11}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[10]={ next_id={12}, type=1, msg="Generally speaking, yes...", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=1, msg="But you may use your preferred way too. It's fine.", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="May I ask—could you teach me how to greet properly?", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=1, msg="This—while not difficult, being asked to teach suddenly makes me unsure what to say...", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=1, msg="In any case, saying hello to others should be correct.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=1, msg="Just like how you greeted me earlier.", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="I think I understand now.", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="Linker, how are you?", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=1, msg="Uh... I-I'm doing fine.", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="So this is [greeting,] it doesn't seem particularly difficult.", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=0, msg="Thank you. I've learned something new again.", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=1, msg="It's nothing, no need for special thanks.", talker_id={}, reward=0, relation={} },
		[27]={ next_id={28}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[28]={ next_id={29}, type=1, msg="If you want to learn how to interact with people, feel free to find me.", talker_id={}, reward=0, relation={} },
		[29]={ next_id={30}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[30]={ next_id={31}, type=1, msg="I understand everyone quite well.", talker_id={}, reward=0, relation={} },
		[31]={ next_id={0}, type=0, msg="Alright.", talker_id={}, reward=0, relation={1111,200} },
} },
		[2]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Linker, I have a question to ask you.", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=1, msg="Sure, go ahead.", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=1, msg="Though you really don't need to speak so formally with me. We can be more casual.", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="My emotion module suggested I use this manner of speech when addressing you.", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="I'll improve next time.", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="May I proceed with my question now?", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=1, msg="...Alright, ask away.", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Are emotions... something precious to humans?", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13,14}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[13]={ next_id={15}, type=1, msg="Most people would think so.", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=1, msg="Yes, emotions are the most important bonds in human relationships.", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="Then... will humans reject those without emotions?", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=1, msg="Why would you think that, Kymia?", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="My emotion module is insufficient. As an AI-provided module, it lacks the richness of genuine human emotions. Thus, I often fail to comprehend the emotions others express.", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="This frequently leads to one outcome: Kymia cannot communicate with humans properly.", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="But... Kymia really wants to be friends with humans.", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="Really wants to be friends with Linker and everyone.", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23,24}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[23]={ next_id={25}, type=1, msg="I am your friend.", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=1, msg="Everyone in Leistance is your friend.", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=0, msg="In non-face-to-face situations, Kymia cannot utilize lie-detection modules to verify your statement.", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=0, msg="Linker, are you really not lying?", talker_id={}, reward=0, relation={} },
		[27]={ next_id={28}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[28]={ next_id={29}, type=1, msg="Of course I'm not lying. Everyone likes Kymia.", talker_id={}, reward=0, relation={} },
		[29]={ next_id={30}, type=0, msg="Kymia... truly has friends now?", talker_id={}, reward=0, relation={} },
		[30]={ next_id={31}, type=0, msg="Since I have friends, which emotional response should Kymia apply when interacting with them?", talker_id={}, reward=0, relation={} },
		[31]={ next_id={32}, type=0, msg="Ah—Kymia should greet them with [How are you?]", talker_id={}, reward=0, relation={} },
		[32]={ next_id={33}, type=0, msg="My apologies for the interruption, Linker.", talker_id={}, reward=0, relation={} },
		[33]={ next_id={34}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[34]={ next_id={0}, type=1, msg="...(Seems I need to find an emotion specialist to properly communicate with Kymia)", talker_id={}, reward=0, relation={1111,200} },
} },
		[3]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Linker, what do you usually like to do?", talker_id={}, reward=0, relation={} },
