		[16]={ next_id={17}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=1, msg="It's truly unexpected.", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=1, msg="I assumed all your experiences would be systematically recorded.", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="Yes, I keep a diary.", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="Father once said the difference between humans and machines lies in personally experiencing the existence and evolution of things.", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="When participating in this process, recording with pen feels more authentic, vivid and immersive than automatic system logs.", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="Father also enjoyed diary-writing.", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=0, msg="Whenever he reviewed his diary, he would always show this... [peculiar] smile.", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=1, msg="Most humans maintain the habit of diary-keeping.", talker_id={}, reward=0, relation={} },
		[27]={ next_id={28}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[28]={ next_id={29}, type=1, msg="But that was long ago.", talker_id={}, reward=0, relation={} },
		[29]={ next_id={30}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[30]={ next_id={31}, type=1, msg="As far as I know, many people don't like writing diaries now", talker_id={}, reward=0, relation={} },
		[31]={ next_id={32}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[32]={ next_id={33}, type=1, msg="Thinking carefully, I don't seem to have particular hobbies.", talker_id={}, reward=0, relation={} },
		[33]={ next_id={34}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[34]={ next_id={35}, type=1, msg="Spending every day with you all already brings me much joy.", talker_id={}, reward=0, relation={} },
		[35]={ next_id={36}, type=0, msg="Being Linker's source of joy is my honor.", talker_id={}, reward=0, relation={} },
		[36]={ next_id={37}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[37]={ next_id={0}, type=1, msg="...(She must have misunderstood something)", talker_id={}, reward=0, relation={1111,200} },
} },
		[4]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Linker, I have a favor to ask.", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=1, msg="What is it?", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=1, msg="Go ahead.", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="I watched a movie the other day.", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="It was about robots interacting with humans.", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="The main character took the robot to a shopping mall to help it understand humans better.", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=1, msg="Kymia,you want to go to the mall?", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Kymia simply wishes to observe more humans in a real-world environment.", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="And at the end of the movie, I saw the robot getting along very well with people.", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="She was well-liked and made many friends.", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="Based on this movie, Kymia concludes that if Linker takes me to the mall, it will help me understand humans faster.", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="Would you be willing to take me?", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=1, msg="Of course I would.", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=1, msg="But Kymia can't go to the mall in your usual duty outfit - it would attract too much attention.", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=1, msg="Remember to change into ordinary clothes.", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="Normal clothes?", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=1, msg="I'll prepare it for you.", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=1, msg="I can look forward to it.", talker_id={}, reward=0, relation={} },
		[27]={ next_id={28}, type=0, msg="Looking forward? Shouldn't you say thank you at this point?", talker_id={}, reward=0, relation={} },
		[28]={ next_id={29}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[29]={ next_id={0}, type=1, msg="...", talker_id={}, reward=0, relation={1111,200} },
} },
		[5]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Linker, are you resting now?", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=1, msg="Not yet.", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Then where are you?", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=1, msg="Just came out from the Tutorial room.", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="That sounds exhausting.", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="You should rest first. We can talk another time.", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=1, msg="It's alright. You can say whatever you want.", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=1, msg="I don't need rest right now.", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Actually it's nothing important...Just that after you took me to the mall last time.", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="I've gained deeper understanding about human communication.", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="I even made new friends.", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="So... I wanted to thank you in person.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=1, msg="Making friends is wonderful. Congratulations.", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=1, msg="Thanking in person? How should I do it?", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="Hmm...", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="After much consideration, I decided to invite you for a meal and a movie.", talker_id={}, reward=0, relation={} },
