		[25]={ next_id={26}, type=0, msg="So this is called a date?", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[27]={ next_id={28}, type=1, msg="...", talker_id={}, reward=0, relation={} },
		[28]={ next_id={29}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[29]={ next_id={30}, type=1, msg="When shall we go?", talker_id={}, reward=0, relation={} },
		[30]={ next_id={31}, type=0, msg="I'll find the right time and prepare properly before notifying you.", talker_id={}, reward=0, relation={} },
		[31]={ next_id={32}, type=2, msg="", talker_id={}, reward=0, relation={} },
