	[1012]={ type=1, hero_id={1012}, name="", talk_part={
		[1]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Raven from the Abyss", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Greetings.", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="Today, the endless darkness extends its wicked claws—", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Using those closest to me as leverage,", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="It seeks to halt the steps of a hero.", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="Just this once,", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="I must ask for your aid.", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=1, msg="...Did you fail math again?", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="The incompetent school demands a guardian's signature.", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Should they see this slanderous document, they will undoubtedly demand I suspend my righteous crusade.", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="Yet another scheme in this wicked world.", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=1, msg="Newcastle refused to sign for you this time?", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="She has been deceived.", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="Sin creeps into every corner of this world.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="It is hard to believe such a vile subject holds mainstream prominence.", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="In any case, Linker—", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="The hour is dire.", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="For the sake of the world's future,", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="I must ask you to stand in my stead.", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="...", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="So, are you signing or not?", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=1, msg="Hello, I am currently unavailable. Please contact me later. [Auto-reply]", talker_id={}, reward=0, relation={} },
		[26]={ next_id={0}, type=0, msg="...Darn adults", talker_id={}, reward=0, relation={1012,200} },
} },
		[2]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Linker.", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="I must emphasize this repeatedly—", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="You must distinguish between my two identities.", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Outside of operations, you cannot use my real name.", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="And during cover maintenance,", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="Do not refer to me by codename,", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="Or discuss mission details.", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=1, msg="What counts as [cover maintenance]?", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="When I'm attending school.", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="You must understand—", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="I am diligently playing the role of a high school girl.", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Given my... unique circumstances,", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="This is no simple task.", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="Yet I flawlessly maintain this double life.", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="No one suspects", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="That I am the Raven who soars through the city by night.", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19,20}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[19]={ next_id={21}, type=1, msg="...You are a high school girl.", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=1, msg="Understood. I will remember you are a high school girl.", talker_id={}, reward=0, relation={} },
		[21]={ next_id={0}, type=0, msg="I am Raven!", talker_id={}, reward=0, relation={1012,200} },
} },
		[3]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Linker.", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="A matter of grave concern has come to my attention.", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="A shadow of malice lurks within HQ.", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Even one born of the abyss like myself", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Feels instinctive unease.", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=1, msg="That serious?", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Extremely.", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="The world is like a labyrinth.", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="Yet there are corners where one may rest.", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Even I must admit—", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="Appropriate comfort on the path of continuing justice", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Very helpful.", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="But now, it has vanished.", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="This... unsettles me.", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=1, msg="Say it in words I understand.", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="The snack tray I saw last visit is gone.", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="This does not hinder me,", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="But its absence", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="May negatively impact", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="The branch's morale.", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=1, msg="...The snacks were eaten yesterday. Next time, give a heads-up—I'll restock.", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=0, msg="I do not eat them.", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=0, msg="They do not hinder me.", talker_id={}, reward=0, relation={} },
		[27]={ next_id={0}, type=0, msg="Are you listening?", talker_id={}, reward=0, relation={1012,200} },
} },
		[4]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Tomorrow, after noon, I will be unavailable.", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="For emergencies,", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="Contact other Dreams Consult fulfillers.", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Raven shall send word upon return.", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Await in silence.", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=1, msg="? But tomorrow's the weekend.", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="True. Tomorrow, I need not hide in mundane guise.", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Normally, an ideal time for justice.", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="But Raven has been called to a higher purpose—", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="To confront destiny,", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="To commune with her soul.", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Thus, she must withdraw from worldly affairs.", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="This is essential for awakening true power—", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=1, msg="I heard there's a signing event for [Eclipse Over Lissugen] tomorrow afternoon.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="So what?", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=1, msg="You, the author, and the protagonist share the exact same name.", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="My name is Korinna.", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=1, msg="You are Raven.", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="I don't care what you think—", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=0, msg="I have nothing to do with that book.", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=0, msg="Tomorrow's affairs are not your concern. Do not ask.", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[27]={ next_id={28}, type=1, msg="...Can you get me Raven's autograph?", talker_id={}, reward=0, relation={} },
		[28]={ next_id={0}, type=0, msg="No!", talker_id={}, reward=0, relation={1012,200} },
} },
		[5]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Linker", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Regarding your previous request, I'm sorry I can't fulfill it.", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="Whether it's a superhero or a high school girl,", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="there's no way to get you", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Raven's autograph.", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=1, msg="But aren't you Raven?", talker_id={}, reward=0, relation={} },
