		[3]={ next_id={4}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=1, msg="What new functions have you learned?", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Audio recording.", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="Grinloffin says it's [high-fidelity.]", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="I once believed electromagnetic waves couldn't convey a song's soul.", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Yet even with some degradation...", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="The act of transmission itself holds meaning.", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="So I recorded some traditional hymns.", talker_id={}, reward=0, relation={} },
