		[12]={ next_id={13}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=1, msg="Uploaded them?!", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="She says many enjoyed it.", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="[Web Link]", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="She calls this a [homepage]?", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="She said it's quite popular.", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=1, msg="...That's the Zulu Mercenary recruitment portal!", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="Is it? I'm unfamiliar.", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="But Grinloffin mentioned our [popularity] and [reputation] improved.", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="So that must be a good thing.", talker_id={}, reward=0, relation={} },
		[23]={ next_id={0}, type=0, msg="Blessed be the Earth Mother, that's wonderful.", talker_id={}, reward=0, relation={1104,200} },
} },
		[3]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Lately, many Leistance Operators inquire about...", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Mother Earth Cult", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="I dislike proselytizing—kindred spirits gather naturally.", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Forced preaching feels... unnatural.", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Any insight, Linker?", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=1, msg="Your earlier recordings may have gone viral.", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="I see.", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="So unseen Operators now know of me through this..., right?", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="Homepage is truly miraculous.", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Modern bards traverse realms without leaving home.", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="Is this progress or regression?", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="I maintain recordings pale beside lived experience.", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="I wonder if they think the same way...", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=1, msg="Perhaps that's precisely why they seek you.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="You console others well, Linker.", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="That warmth explains your approachability.", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="Nature, the earth... should embody embrace and kinship.", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="Such souls receive nature's blessings.", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="In this endless night era...", talker_id={}, reward=0, relation={} },
		[22]={ next_id={0}, type=0, msg="Knowing you is a grace.", talker_id={}, reward=0, relation={1104,200} },
} },
		[4]={ talk_group={
