		[5]={ next_id={6}, type=0, msg="Certain activities?", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=1, msg="What kind specifically?", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Crop cultivation. And animal husbandry.", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=1, msg="...Pardon?", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Planting. And livestock rearing.", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="Strange, does text also suffer poor reception?", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=1, msg="No... my apologies. Just surprised.", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="Oh, that's understandable too.", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="People in the fortress city should rarely engage in such activities.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="But outside the fortress city", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="People's means of living can't be highly planned.", talker_id={}, reward=0, relation={} },
