		[2]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Linker, is daily life at Leistance always like this?", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Hmm?", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="It's... not what I imagined.", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="So in your imagination, what is Leistance Security like?", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="I imagine this place is like a Tutorial ── going on missions ── coming back to the infirmary to rest ── then going on missions again.", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="Repeat until combat-ready no more.", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8,9}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[8]={ next_id={10}, type=1, msg="I'd have resigned long ago.", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=1, msg="Your version of Leistance sounds terrifying.", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="But now it feels no different from being on the fleet.", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=1, msg="Tell me about your naval routines?", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Gladly!", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="Life in our fleet is very interesting, every day is full of various thrills and challenges.", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=1, msg="So what do you usually do?", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="We usually conduct Tutorials and regular patrols to protect the safety of the sea area.", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="We also need to handle ship maintenance and support tasks to ensure the fleet's vessels and equipment operate smoothly.", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="Of course, the most important thing is to expel the [invading forces].", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21,22}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[21]={ next_id={23}, type=1, msg="Sounds demanding.", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=1, msg="Any downtime?", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="Of course, there is.", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=0, msg="Plenty!", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=0, msg="Movies, cards, gym sessions...", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=0, msg="Even won a fishing tournament somehow.", talker_id={}, reward=0, relation={} },
		[27]={ next_id={28}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[28]={ next_id={29}, type=1, msg="Sounds lively.", talker_id={}, reward=0, relation={} },
		[29]={ next_id={30}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[30]={ next_id={31}, type=1, msg="I can tell you all have a deep bond, and you really miss your comrades.", talker_id={}, reward=0, relation={} },
		[31]={ next_id={32}, type=0, msg="Yes.", talker_id={}, reward=0, relation={} },
		[32]={ next_id={33}, type=0, msg="But after spending some time together, I found that everyone at Leistance is also very friendly.", talker_id={}, reward=0, relation={} },
		[33]={ next_id={0}, type=0, msg="I believe it won't take too long to fit into this big family nicely.", talker_id={}, reward=0, relation={1002,200} },
} },
		[3]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Linker, I heard you were looking for me?", talker_id={}, reward=0, relation={} },
