		[10]={ next_id={11}, type=0, msg="The truth is, the Leistance Security Bureau's cafeteria is just too good.", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Every day there's so much delicious food—I can't help myself.", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="All that eating has been... showing on the scale.", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="If I don't train extra, something terrifying will happen.", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=1, msg="Something serious?", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="An exemplary soldier must maintain peak physical condition.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="Shouldn't you just... eat more carefully?", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Honestly, back in the fleet, we were stuck at sea for months.", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="The food I eat is quite simple, though frozen vegetable packs taste pretty good too.", talker_id={}, reward=0, relation={} },
