		[26]={ next_id={27}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[27]={ next_id={0}, type=1, msg="You can definitely do it.", talker_id={}, reward=0, relation={1002,200} },
} },
		[5]={ talk_group={
