		[19]={ next_id={20}, type=0, msg="(✺ω✺)", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="o(╥﹏╥)o", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="Linker, you haven't taken me out in ages!", talker_id={}, reward=0, relation={} },
