		[3]={ next_id={5}, type=1, msg="Going to rest.", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=1, msg="Why aren't you asleep yet, little one?", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="I can't sleep.", talker_id={}, reward=0, relation={} },
