		[7]={ next_id={8}, type=0, msg="I miss Mom. So, so much.", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Do you… think she'll ever come back?", talker_id={}, reward=0, relation={} },
