		[16]={ next_id={17}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=1, msg="Think of something else that makes you happy?", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="No! I only want Mom! (T ^ T)", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="Today, I passed by the amusement park.", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="All the other kids had their moms and dads with them.", talker_id={}, reward=0, relation={} },
