		[17]={ next_id={18}, type=1, msg="What about your emergency stash?", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Ate it all.", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="And last night, the sisters came over to hang out.", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="So we happily finished all the snacks together.", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="But then late at night—", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="Usually, the HR sisters leave treats for me!", talker_id={}, reward=0, relation={} },
