		[24]={ next_id={25}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=1, msg="Because you ate them all, didn't you?", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=0, msg="But hunger is unstoppable!", talker_id={}, reward=0, relation={} },
		[27]={ next_id={28}, type=0, msg="Ever since becoming an AIMBS Operator, it's been like this…", talker_id={}, reward=0, relation={} },
		[28]={ next_id={29}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[29]={ next_id={30}, type=1, msg="You're hopeless.", talker_id={}, reward=0, relation={} },
		[30]={ next_id={31}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[31]={ next_id={32}, type=1, msg="Fine. I'll set up an emergency snack cabinet—only for real emergencies!", talker_id={}, reward=0, relation={} },
		[32]={ next_id={33}, type=0, msg="Linker really is the best!", talker_id={}, reward=0, relation={} },
