		[16]={ next_id={17}, type=0, msg="One day I got up late.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="I opened the base gate—", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Beams of light piercing the sky!", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="But tiny me panicked", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="running under the table while shouting.", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="[The sky's breaking! Run!!]", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="The logistics team was all taking a break.", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="When they hear me shout, quickly run out and see what's going on.", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=0, msg="They opened the door and took a look.", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=0, msg="Only to find auroras.", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27,28}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[27]={ next_id={29}, type=1, msg="Hahaha", talker_id={}, reward=0, relation={} },
		[28]={ next_id={29}, type=1, msg="Then?", talker_id={}, reward=0, relation={} },
		[29]={ next_id={30}, type=0, msg="They tried pulling me from under the table.", talker_id={}, reward=0, relation={} },
		[30]={ next_id={31}, type=0, msg="I wouldn't do it even if I died.", talker_id={}, reward=0, relation={} },
		[31]={ next_id={32}, type=0, msg="I just hold on to the table leg and don't move.", talker_id={}, reward=0, relation={} },
		[32]={ next_id={33}, type=0, msg="Ate there. Slept there.", talker_id={}, reward=0, relation={} },
		[33]={ next_id={34}, type=0, msg="Until the auroras faded and my parents returned.", talker_id={}, reward=0, relation={} },
		[34]={ next_id={35,36}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[35]={ next_id={37}, type=1, msg="Must've been terrifying...", talker_id={}, reward=0, relation={} },
		[36]={ next_id={37}, type=1, msg="A bit.", talker_id={}, reward=0, relation={} },
		[37]={ next_id={38}, type=0, msg="Yeah", talker_id={}, reward=0, relation={} },
		[38]={ next_id={39}, type=0, msg="But after their explanation,", talker_id={}, reward=0, relation={} },
		[39]={ next_id={40}, type=0, msg="I loved auroras!", talker_id={}, reward=0, relation={} },
		[40]={ next_id={41}, type=0, msg="If the aurora appears again, we can all enjoy it together.", talker_id={}, reward=0, relation={} },
		[41]={ next_id={42}, type=0, msg="Speaking of which, now I want to watch them with you~", talker_id={}, reward=0, relation={} },
		[42]={ next_id={43,44}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[43]={ next_id={45}, type=1, msg="We'll find a chance.", talker_id={}, reward=0, relation={} },
		[44]={ next_id={45}, type=1, msg="Me too", talker_id={}, reward=0, relation={} },
		[45]={ next_id={46}, type=0, msg="Promise?", talker_id={}, reward=0, relation={} },
		[46]={ next_id={47}, type=0, msg="Next Arctic trip—", talker_id={}, reward=0, relation={} },
		[47]={ next_id={0}, type=0, msg="Aurora date!", talker_id={}, reward=0, relation={1306,200} },
} },
