	[1305]={ type=1, hero_id={1305}, name="", talk_part={
		[1]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Um... Linker...", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=1, msg="What's up?", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="I saw in the news that many people like the smell of gasoline or paint.", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Isn't that weird?", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=1, msg="Probably attracted to certain chemicals in them?", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="That makes sense.", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Like how some prefer floral scents while others like woody aromas.", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=1, msg="Preferences vary between people.", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="Speaking of which, what scents do you like, Linker?", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=1, msg="Me?", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=1, msg="Upon thinking, I don't seem to have a special preference.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=1, msg="What about Gomiya?", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="Hmm...", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="I've spent my childhood in my family's toy workshop.", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="For me, it's probably the smell of [tools and materials].", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=1, msg="[Tools and materials]?", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=0, msg="Cut leather, hammered metal, and glue!", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=0, msg="These smells make me feel at peace.", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[27]={ next_id={0}, type=1, msg="The scent of childhood memories.", talker_id={}, reward=0, relation={1305,200} },
} },
		[2]={ talk_group={
