		[2]={ next_id={3}, type=0, msg="Emergency!", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="Only you can help!", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=1, msg="What happened?", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="Isis restricted my field access.", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="If I can't go out to do research, I'll totally ruin my career.", talker_id={}, reward=0, relation={} },
