		[9]={ next_id={10}, type=1, msg="Ah, that.", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=1, msg="Restricted just means no midnight excursions, no?", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="That's true result-wise, but from a plant research perspective...", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="There are many mutant plants in the Void Expanse that are only active at night.", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="If I can't go out at night, I can't record them.", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="This would be devastating for me!", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=1, msg="I'll plead your case...", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=1, msg="But what if you encounter dangers?", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=1, msg="Isis banned outings after your last [trip] nearly got you killed by mutants.", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="Solved that!", talker_id={}, reward=0, relation={} },
