		[24]={ next_id={25}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=1, msg="Just you two... safe?", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[27]={ next_id={28}, type=1, msg="How about this, I'll go with you guys.", talker_id={}, reward=0, relation={} },
		[28]={ next_id={29}, type=0, msg="Really? That's great!", talker_id={}, reward=0, relation={} },
		[29]={ next_id={30}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[30]={ next_id={31}, type=1, msg="Ah, but I can't go every day.", talker_id={}, reward=0, relation={} },
		[31]={ next_id={32}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[32]={ next_id={33}, type=1, msg="Once a week at most, okay?", talker_id={}, reward=0, relation={} },
