		[8]={ next_id={9}, type=0, msg="Just know that Bulu is technically a type of plant.", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="So, it needs sunlight and water too.", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=1, msg="Another Research Department creation?", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="No.", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Bulu is a pet I brought from my hometown.", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="In Leistance, Bulu is my only family.", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=1, msg="Bulu means a lot to you, huh?", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="Yes.", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="He's a creature Vivian and I raised together.", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=1, msg="Vivian?", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="Yeah, Vivian was my closest friend.", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="Just...", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="Let's skip that topic for now.", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=0, msg="Anyway, thank you, Linker.", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=0, msg="If possible, I'd like to thank you in person.", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[27]={ next_id={28}, type=1, msg="No need. Honestly, I didn't do much.", talker_id={}, reward=0, relation={} },
		[28]={ next_id={29}, type=0, msg="Alright, if you say so.", talker_id={}, reward=0, relation={} },
		[29]={ next_id={30}, type=0, msg="Then, let me gift you one of my newly cultivated plants.", talker_id={}, reward=0, relation={} },
		[30]={ next_id={31}, type=0, msg="It purifies the air and emits a calming scent.", talker_id={}, reward=0, relation={} },
		[31]={ next_id={32}, type=0, msg="Many Operators say it works wonders.", talker_id={}, reward=0, relation={} },
		[32]={ next_id={33}, type=0, msg="Don't forget to claim it.", talker_id={}, reward=0, relation={} },
		[33]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=1021, relation={} },
} },
}
