	[1206]={ type=1, hero_id={1206}, name="", talk_part={
		[1]={ talk_group={
		[1]={ next_id={2}, type=0, msg="You seem quite interested in my auxiliary mechanical arms?", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=1, msg="Sorry, was I that obvious?", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=1, msg="They move so fluidly, almost like they're part of your body.", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="You could say they are.", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="My body has adapted to them quite well.", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Though...", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Sometimes they do fight each other.", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=1, msg="Huh?", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="When multitasking, they might bump into each other.", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Like how teeth accidentally bite lips when we're frustrated.", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="Minor issues.", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=1, msg="Sounds like they've integrated perfectly with you.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="Yeah.", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Sometimes I even forget they're exoskeletal.", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="At night, I'd reach for a glass of water with them—", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="only to remember I've already taken them off.", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="That moment always gives me this feeling of,", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="Ah, this feels so unnatural.", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="That feeling.", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=0, msg="I should optimize them further, make them comfortable enough to wear even while sleeping.", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=1, msg="As expected of a prosthetics expert!", talker_id={}, reward=0, relation={} },
		[27]={ next_id={28}, type=0, msg="Heh, flattery won't get you anywhere.", talker_id={}, reward=0, relation={} },
		[28]={ next_id={29}, type=0, msg="Though, speaking of which, I just thought of a good optimization path.", talker_id={}, reward=0, relation={} },
		[29]={ next_id={30}, type=0, msg="I'll get to work now.", talker_id={}, reward=0, relation={} },
		[30]={ next_id={31}, type=0, msg="Let's chat later.", talker_id={}, reward=0, relation={} },
		[31]={ next_id={32}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[32]={ next_id={0}, type=1, msg="Sure.", talker_id={}, reward=0, relation={1206,200} },
} },
		[2]={ talk_group={
		[1]={ next_id={2}, type=0, msg="The recent adjustments worked well.", talker_id={}, reward=0, relation={} },
