		[3]={ next_id={4}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=1, msg="Congrats!", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=1, msg="Next time we meet, you'll have to show me properly.", talker_id={}, reward=0, relation={} },
