		[8]={ next_id={9}, type=0, msg="Definitely.", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Since you're so interested...", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="Want to try swapping prosthetics? Custom styles available.", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="As a bonus for our successful link-up,", talker_id={}, reward=0, relation={} },
