		[13]={ next_id={14}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=1, msg="Can someone without injuries still get prosthetics?", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="Of course.", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="Prosthetics these days aren't just medical replacements for injuries.", talker_id={}, reward=0, relation={} },
