		[25]={ next_id={26}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[26]={ next_id={0}, type=1, msg="Okay", talker_id={}, reward=0, relation={1206,200} },
} },
		[3]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Do you need a clock?", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=1, msg="Hm? Probably... not?", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=1, msg="Why?", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="I saw some antique clocks at the parts dealer", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="and couldn't resist buying a few.", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="But I don't sleep well at night.", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="and my hearing's sharp.", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="If I kept them in my room,", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="the ticking would probably keep me awake.", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="So I figured I'd ask if anyone wants them.", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="At least this way, I can still admire them occasionally.", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=1, msg="I don't mind keeping them.", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=1, msg="Didn't expect Artisan to be into clocks.", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Yes.", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="Old-world clocks have such intricate mechanical designs.", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="I love studying them.", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="When the gears turn,", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="there's this strange sense of inevitability—", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="Just like the encounters in our life", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=0, msg="When experiencing it, I always think it's unexpected,", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=0, msg="but from an outsider's perspective,", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=0, msg="maybe everything was predetermined.", talker_id={}, reward=0, relation={} },
		[27]={ next_id={28}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[28]={ next_id={29}, type=1, msg="Didn't take Artisan for a fatalist.", talker_id={}, reward=0, relation={} },
		[29]={ next_id={30}, type=0, msg="Just rambling. Don't take it too seriously.", talker_id={}, reward=0, relation={} },
		[30]={ next_id={31}, type=0, msg="So, should I bring the clocks over now?", talker_id={}, reward=0, relation={} },
		[31]={ next_id={32}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[32]={ next_id={0}, type=1, msg="Sure, come on over.", talker_id={}, reward=0, relation={1206,200} },
} },
		[4]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Want to tour my workshop?", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=1, msg="Is that alright? I heard your workshop is usually off-limits.", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Normally, yes.", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="But today's a special case.", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=1, msg="How so?", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="I'm reorganizing the workshop.", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Once it's done, it'll be at its cleanest—", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="perfect for showing off.", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12,13}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[12]={ next_id={15}, type=1, msg="Why the sudden cleanup?", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=1, msg="Need help?", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="No, only I know where things should go.", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="I can find stuff quickly even when it's messy,", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="but constantly hearing complaints about the clutter does get annoying.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="After this tour, you'll have to vouch for me.", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19,20}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[19]={ next_id={21}, type=1, msg="...So that's what this is about?", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=1, msg="Don't worry too much about others' opinions.", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="If we're talking about others' opinions,", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="I really don't care much.", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="That's why I only invited you today.", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25,26}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[25]={ next_id={27}, type=1, msg="I never thought your workshop was messy.", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=1, msg="Hm?", talker_id={}, reward=0, relation={} },
		[27]={ next_id={28}, type=0, msg="Anyway, come see my pristine workshop.", talker_id={}, reward=0, relation={} },
		[28]={ next_id={0}, type=0, msg="My very concerned Linker.", talker_id={}, reward=0, relation={1206,200} },
} },
		[5]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Do you believe in [Mechanical Eternity]?", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=1, msg="What's that?", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="For example—", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="If your entire body were mechanical, with only your brain remaining organic, would you still be yourself?", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7,8}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[7]={ next_id={9}, type=1, msg="Of course.", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=1, msg="I... don't know.", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Then, if you had to choose one body part for prosthetics, what would it be?", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=1, msg="Can I opt out?", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="No. You must choose.", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=1, msg="Hmm...", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="Oh? Struggling that much?", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="But if I were modifying you,", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="the choice would be easy.", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=1, msg="Where would you modify?", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="Well, how about starting with the heart?", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="I've never operated on one before.", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="I'm a little curious about what Linker's heart looks like.", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="Wait here—I'll prep the tools.", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=0, msg="No appointment needed this time~", talker_id={}, reward=0, relation={} },
		[25]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=1021, relation={} },
} },
}
