		[15]={ next_id={16}, type=0, msg="Can you hold your liquor?", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="Come by my bar, [Moonlight Kiss,] sometime.", talker_id={}, reward=0, relation={} },
