		[19]={ next_id={20}, type=0, msg="Would you visit my homeland with me someday, Linker?", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="Just feel like... with Linker by my side at that time", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="It would be less daunting", talker_id={}, reward=0, relation={} },
