		[16]={ next_id={17}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=1, msg="Glad you enjoyed it.", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Yet one machine perplexed me—", talker_id={}, reward=0, relation={} },
