		[6]={ next_id={7}, type=1, msg="That shady business owner!", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="My, my.", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Whatever gave you that impression?", talker_id={}, reward=0, relation={} },
