		[10]={ talk_group={
		[1]={ next_id={2}, type=0, msg="At this moment, a nameless hero passing by faces one of life's greatest crises", talker_id={1012}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Is it an enemy? Or perhaps a long-planned conspiracy?", talker_id={1012}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="Raven is caught in an invisible web at night. If she doesn't act soon...", talker_id={1012}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="She thinks this might be her final chance...", talker_id={1012}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Didn't pass this time either?", talker_id={1303}, reward=0, relation={} },
		[6]={ next_id={7}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=1, msg="Again?", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Again.", talker_id={1105}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="A hero won't be bound by mere numbers", talker_id={1012}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="I've prepared absence notes for the entire semester, each with different reasons", talker_id={1012}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Flawless execution.", talker_id={1012}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="So what's your crisis about?", talker_id={1303}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="It's still that... Could you please sign my report card, Boss...", talker_id={1012}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="[File attachment]", talker_id={1012}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="Signed. Payment remains the same as before~", talker_id={1303}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="I still can't quite understand this grade culture here...", talker_id={1105}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="Quantifying people with numbers seems rather strange.", talker_id={1105}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Spark doesn't have exams?", talker_id={1012}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="We do, but not numerically graded.", talker_id={1105}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="Our sect has various tests - riding cranes, wrestling bears...", talker_id={1105}, reward=0, relation={} },
		[21]={ next_id={22}, type=2, msg="", talker_id={}, reward=0, relation={} },
