		[12]={ next_id={13}, type=0, msg="Seeing hospital patients recover gives a sense of rewarding effort", talker_id={1301}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="This time it's because a nurse who once cared for me is retiring", talker_id={1301}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="I went to visit her specially", talker_id={1301}, reward=0, relation={} },
		[15]={ next_id={16}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=1, msg="Miss Lilira is very kind~", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="Kindness requires following doctor's orders meow~", talker_id={1205}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Otherwise Lilira turns into a devil meow~", talker_id={1205}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="I suspect you're mocking me, dumb cat~", talker_id={1202}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="Yuanya's usually well-behaved though~", talker_id={1301}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="See you all tonight.", talker_id={1301}, reward=0, relation={} },
		[22]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
		[9]={ talk_group={
		[1]={ next_id={2}, type=0, msg="[Image message]", talker_id={1205}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Look, a new kitty!", talker_id={1205}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="Wow, so cute!", talker_id={1301}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Silly Meow went to find strays again? What about Little Flower from last time?", talker_id={1202}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Couldn't find Little Flower at the usual spot. Don't know where it went to play~", talker_id={1205}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="This one is Little White", talker_id={1205}, reward=0, relation={} },
		[7]={ next_id={8}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=1, msg="Did Koraz name it?", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Of course meow", talker_id={1205}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="Stray cats don't have names, so I name them properly!", talker_id={1205}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Properly huh... You wore out your textbook doing it", talker_id={1202}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="Little Flower, Little White, Little Black, White Gloves, Black Gloves, Fluffball...", talker_id={1202}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="I feel like we have different definitions of [proper] meow~", talker_id={1205}, reward=0, relation={} },
		[14]={ next_id={15}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=1, msg="They're all cute", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="Koraz goes to the city every month to play with strays", talker_id={1301}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="Because Silly Meow is severely allergic to cats - almost got hospitalized as a kid playing with them", talker_id={1202}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Now has to suit up completely to visit cats", talker_id={1202}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="Even then still gets allergies sometimes", talker_id={1202}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="@Koraz I made you a filtration device. Wear it next time and you won't sneeze!", talker_id={1305}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="Thank you Gomia meow~", talker_id={1205}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="Now I can get close with kitties meow!", talker_id={1205}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="You're welcome~", talker_id={1305}, reward=0, relation={} },
		[24]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
		[10]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Everyone, the new mission reports are due", talker_id={1301}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="I've finished mine. Send yours to me tonight - I'll submit them to the Chief", talker_id={1301}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="AHHHHH", talker_id={1202}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="MEOWHHHH", talker_id={1205}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="I'm done too, just need some revisions", talker_id={1305}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="As expected of Gomia", talker_id={1301}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="Yuanya and Koraz, do your best~", talker_id={1301}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Seriously, why do AIMBS need to write mission reports?", talker_id={1202}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="I can't write at all!", talker_id={1205}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="Silly Meow probably can't even write one word meow~", talker_id={1202}, reward=0, relation={} },
		[11]={ next_id={12}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=1, msg="Even AIMBS aren't spared from homework troubles huh", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="There's just too much to report", talker_id={1305}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="I'm used to writing academic papers, but it must be really hard for Yuanya and Koraz?", talker_id={1305}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="Yes meow~", talker_id={1205}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="Let me think... damaged public property, consumed medical supplies and resources... next mission's budget...", talker_id={1202}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="This is way too difficult!", talker_id={1202}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Same meow! When fighting mutants, who pays attention to whether the floor gets damaged meow!", talker_id={1205}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="Don't worry everyone, no need to be that detailed~", talker_id={1301}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="But Lilira always writes extremely thorough reports...", talker_id={1305}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="Is this the self-discipline of an honor student?", talker_id={1202}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="Ahaha...", talker_id={1301}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="Anyway, let's all do our best to finish writing~", talker_id={1301}, reward=0, relation={} },
		[24]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
}
},
	[2003]={ type=2, hero_id={1202,1305,1301,1205,1206,1207,1004,1111,1201,1101,1110,1307,1109,1302,1208,1007,1006}, name="All hail Lady Isis!", talk_part={
		[1]={ talk_group={
		[1]={ next_id={2}, type=0, msg="@everyone A6 just received a complaint from Logistics - two patrol drones went missing from the 4th floor dorm hallway last night.", talker_id={1301}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Anyone seen them?", talker_id={1301}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="I did equipment updates on the drones yesterday. I'm sure I returned them all.", talker_id={1305}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Yuanya was gaming in her room all night. Didn't see anything~", talker_id={1202}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="I was at the hospital too. Didn't notice anything strange.", talker_id={1301}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="Not my area of interest.", talker_id={1206}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="Oh, this is troublesome.", talker_id={1301}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Why disappear right during surveillance maintenance?", talker_id={1301}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Maybe Gomia messed up the repairs meow?", talker_id={1205}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="And the drones flew away meow?", talker_id={1205}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Impossible!", talker_id={1305}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="I'd never make such a basic mistake!", talker_id={1305}, reward=0, relation={} },
		[13]={ next_id={14}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=1, msg="What about the drones' built-in tracking?", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="The tracking system just got upgraded - still calibrating and currently offline.", talker_id={1305}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="Surely no one would treat drones as toys and hide them...?", talker_id={1202}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="Ah, now that you mention it...", talker_id={1110}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Come to think of it...", talker_id={1305}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="That new kid, right? Heard she already broke several drones since arriving.", talker_id={1301}, reward=0, relation={} },
		[20]={ next_id={21}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=1, msg="Corrosicat?", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="Yes. We already found them in her room.", talker_id={1301}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="Well, at least they're recovered.", talker_id={1305}, reward=0, relation={} },
		[24]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
		[2]={ talk_group={
		[1]={ next_id={2}, type=0, msg="I saw someone new at HQ with mechanical arms like Gomia.", talker_id={1110}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Heard they're a prosthetic doctor, but doesn't seem very approachable.", talker_id={1110}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="What? When did this happen?!", talker_id={1305}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="At Logistics?", talker_id={1305}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Gomia gets excited at [maintenance]~", talker_id={1202}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="That doctor should be organizing personal items at Logistics now.", talker_id={1110}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="Gomia can go take a look if interested.", talker_id={1110}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="I'm on my way.", talker_id={1305}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="What's a prosthetic doctor meow? Like Gomia?", talker_id={1205}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="Different from engineers~", talker_id={1202}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Prosthetic doctors mainly work with patients needing prosthetics -", talker_id={1301}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="making artificial limbs, repairs, sometimes modifications.", talker_id={1301}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Like our exoskeleton frames?", talker_id={1205}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="Similar idea~", talker_id={1301}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="People who lose limbs need prosthetics to live normally.", talker_id={1301}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="Extremely important work.", talker_id={1301}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="Thanks for the recognition.", talker_id={1206}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Wow, there it is!", talker_id={1202}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="I'm Artisan, the new prosthetic doctor.", talker_id={1206}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="If anyone needs mechanical body modifications, my door's always open.", talker_id={1206}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="Full-body conversions get a discount~", talker_id={1206}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="Eh? You can replace your whole body with machines?", talker_id={1110}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="How does that even work?", talker_id={1110}, reward=0, relation={} },
		[24]={ next_id={25}, type=0, msg="Wanna try?", talker_id={1206}, reward=0, relation={} },
		[25]={ next_id={26}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=1, msg="NO SHE DOESN'T!", talker_id={}, reward=0, relation={} },
		[27]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
		[3]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Vilatria Church's exclusive amulet is here!", talker_id={1207}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="In this world full of competition, danger, and the unknown, everyone needs a sense of security and protective power.", talker_id={1207}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="We are offering you this very power! The amulet is blessed by the Vilatria Church bishop, shielding you from negative energy, keeping you away from virtual particles and evil, and bringing more peace to your mind and stability to your energy.", talker_id={1207}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Buying now includes customized benefits, only 998 dollars! Only 998 dollars!", talker_id={1207}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="What are you still hesitating for? Come and buy it now!", talker_id={1207}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="[Link message]", talker_id={1207}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="Hmm, seems useful.", talker_id={1110}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="998 dollars?", talker_id={1110}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Yes, yes! Purchasing now includes custom patterns～ Alicia, want one?", talker_id={1207}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="Buy one for Linker too～", talker_id={1207}, reward=0, relation={} },
		[11]={ next_id={12}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=1, msg="...", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Not interested.", talker_id={1004}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="This kind of thing is obviously a scam!", talker_id={1202}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="Huh?", talker_id={1110}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="My database has records about Vilatria, but there's no mention of limited-edition amulets...", talker_id={1111}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="Ah… what amulet?", talker_id={1201}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Deling, you're from Vilatria too, right? Do you really have this kind of amulet?", talker_id={1305}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="Don't doubt me～ Our amulets are super effective～ Deling, back me up here.", talker_id={1207}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="Rather than the bishop, it'd be more believable if you said you blessed them yourself :)", talker_id={1201}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="It was blessed by the bishop～", talker_id={1207}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="Special discount if you buy today～ I'll be waiting for everyone in the common area～", talker_id={1207}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="Unauthorized vending within Security Bureau premises prohibited. Confiscated with a warning.", talker_id={1101}, reward=0, relation={} },
		[24]={ next_id={25}, type=0, msg="Whoa, Instructor Lionblade is here.", talker_id={1202}, reward=0, relation={} },
		[25]={ next_id={26}, type=0, msg="I knew this would happen (shakes head).", talker_id={1201}, reward=0, relation={} },
		[26]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
		[4]={ talk_group={
		[1]={ next_id={2}, type=0, msg="@everyone Forwarding an announcement:", talker_id={1101}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="The new round of the Leistance Internal AIMBS Joint Exercise has begun! Considering each combatant's unique strengths, we've designed new competition rules with even richer rewards. Please participate actively and sign up promptly.", talker_id={1101}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="Additionally, the combatants on this list are required to participate.", talker_id={1101}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="[Rules for the XXth Leistance Internal Joint Exercise][Participant List]", talker_id={1101}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Already signed up. This time, the championship is mine.", talker_id={1004}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="My my, Ling is as fired up as ever.", talker_id={1307}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="...", talker_id={1004}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="I won't lose to you a second time.", talker_id={1004}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Looking forward to facing you again～", talker_id={1307}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="Everyone's so motivated! In that case, let's start drafting a training plan～ If needed, I'll be ready in the Medical Division to assist at any time.", talker_id={1301}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Ah… Of course, I'm on the list again. This is torture.", talker_id={1202}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="Can I skip it?", talker_id={1202}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="No. Yuanya, you haven't exercised in too long. Take this chance to train properly.", talker_id={1305}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="T-Training…?", talker_id={1202}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="I should start training too. Let's all do our best!", talker_id={1110}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="Alicia's also full of energy, meow~", talker_id={1205}, reward=0, relation={} },
		[17]={ next_id={18}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=1, msg="I'll be supervising you.", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="Why is everyone so motivated?! I haven't even finished my game yet—", talker_id={1202}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="Ah, she ran away, meow.", talker_id={1205}, reward=0, relation={} },
		[21]={ next_id={22}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=1, msg="…She's gone.", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="Anyway, leave the equipment to me. Let's work hard together.", talker_id={1305}, reward=0, relation={} },
		[24]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
		[5]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Um, has anyone seen Yuanya?", talker_id={1305}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="We've searched the entire dorm area and haven't found her all day.", talker_id={1305}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="Did the pressure get to her after all?", talker_id={1110}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Did you check the recreation zone?", talker_id={1110}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Nope, meow.", talker_id={1205}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="Yuanya didn't come by my place either.", talker_id={1301}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="Where could she be, meow?", talker_id={1205}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Maybe she's secretly training somewhere. No need to worry too much.", talker_id={1110}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Rather than training, I'd believe she's hiding to sleep, meow.", talker_id={1205}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="Anyway, should we check the place Yuanya would least likely be?", talker_id={1110}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="I'll go take a look first.", talker_id={1305}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="If you're looking for that short, pink-haired girl, she did show up in the training room.", talker_id={1004}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Pink hair and short… That's Yuanya, right?", talker_id={1301}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="Is she still there?", talker_id={1305}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="No.", talker_id={1004}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="Huh?", talker_id={1305}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="I think I know where she might be, meow.", talker_id={1205}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Let's check the cafeteria, meow.", talker_id={1205}, reward=0, relation={} },
		[19]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
		[6]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Sorry for worrying everyone. We found Yuanya.", talker_id={1305}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Good. Where was she?", talker_id={1110}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="She was asleep on a cafeteria table, meow.", talker_id={1205}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Didn't even eat her snacks, meow.", talker_id={1205}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="We've already brought her back to the dorm. She's sleeping so soundly she didn't even wake up.", talker_id={1305}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="Only three hours of training and she's already this exhausted? Your branch's AIMBS standards are lacking.", talker_id={1004}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="Yuanya training for that long is already impressive, meow.", talker_id={1205}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="The question is how many days she'll keep it up.", talker_id={1305}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="If my opponents are all this lax, the outcome of this competition is already obvious.", talker_id={1004}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="We'll give it our all too.", talker_id={1305}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Hope so. I won't hold back.", talker_id={1004}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="Somehow… this feels like it'll be tough.", talker_id={1110}, reward=0, relation={} },
		[13]={ next_id={14}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=1, msg="Let's do our best together!", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="We can't be looked down on, meow. Even Yuanya's secretly putting in effort, meow.", talker_id={1205}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="In a way, Ling's motivating you all, huh?", talker_id={1307}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="Looking forward to your performance～", talker_id={1307}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Vilatria's blessed amulets—wish upon them now for a boost to win big prizes!", talker_id={1207}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="You're on the mandatory list too. Hurry up and get to training.", talker_id={1006}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="Eek.", talker_id={1207}, reward=0, relation={} },
		[21]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
		[7]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Whew, so tired…", talker_id={1202}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Finally, I can binge on cola and snacks again! I was starving during training.", talker_id={1202}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="In the end, we still didn't get first place. Haha.", talker_id={1305}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Everyone did their best.", talker_id={1110}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Hehe, the rewards aren't bad either, meow~", talker_id={1205}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="Hoho, a snack gift set! Thanks, Chief Isis.", talker_id={1202}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="You performed decently.", talker_id={1101}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Thanks for the praise, Coach!", talker_id={1202}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="I wasn't finished.", talker_id={1101}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="You did fine, but it's far from what I expected. From now on, someone will supervise your training.", talker_id={1101}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Yes, Flying Fish Squad will strive harder!", talker_id={1305}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="My time is valuable. You'd better mean that.", talker_id={1004}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Don't tell me our trainer is…", talker_id={1202}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="That's right. Ling, this year's champion, is the best person to whip you into shape.", talker_id={1101}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="This is gonna be strict, meow…", talker_id={1205}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="Come to the training room now. Don't waste my time.", talker_id={1004}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="……", talker_id={1202}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="We're on our way!", talker_id={1305}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="As expected, she's relentless…", talker_id={1301}, reward=0, relation={} },
		[20]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
		[8]={ talk_group={
		[1]={ next_id={2}, type=0, msg="@everyone The annual performance evaluation report submission for Lissugen Branch has begun. Remember to upload all required materials by this weekend.", talker_id={1101}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="This affects next year's budget and assignments, so everyone must complete it carefully.", talker_id={1101}, reward=0, relation={} },
		[3]={ next_id={4}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=1, msg="The busiest time of year again...", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Let's see... performance reports, mission summaries, work plans, monthly reports... so much paperwork.", talker_id={1305}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="Why are there grade transcripts too meow?", talker_id={1205}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="Um... do combat liaisons need to submit too?", talker_id={1207}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Yes.", talker_id={1101}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Centaurea's report will probably be [100 Ways to Make Money].", talker_id={1201}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="Report... thesis... that... already submitted.", talker_id={1109}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Remember to submit training schedules too - detailed down to the minute.", talker_id={1101}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="Yes, Instructor!", talker_id={1110}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Too... too strict...?", talker_id={1202}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="Submitted.", talker_id={1004}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="Wow... is this what honor students do meow?", talker_id={1205}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="Need to fill this out properly... should reorganize the prepared materials...", talker_id={1301}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="No idea how to organize this!", talker_id={1202}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="No choice... let's sort it out together tonight.", talker_id={1305}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="I'll help too.", talker_id={1301}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="So reliable, Lilira!", talker_id={1202}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="I'll join meow~", talker_id={1205}, reward=0, relation={} },
		[22]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
		[9]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Cafeteria fish#￥&...&", talker_id={1302}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Food", talker_id={1302}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="Wow, Corrosicat learned to use the communicator! Good job~", talker_id={1110}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Seems like she's expressing something meow.", talker_id={1205}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="What is it meow?", talker_id={1205}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="Whatever it is, doesn't seem good... what about the cafeteria fish?", talker_id={1202}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="Ah, might be my fault...", talker_id={1206}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Adjusted her mechanical arm today - still seems a bit stiff.", talker_id={1206}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Full-body replacement would definitely improve adaptability though~", talker_id={1206}, reward=0, relation={} },
		[10]={ next_id={11}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=1, msg="Don't say scary things so casually like that.", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="Medical's on rotation break today - I'll check Corrosicat's room.", talker_id={1301}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Hope she didn't get food poisoning.", talker_id={1301}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="What happened to the canteen fish? It's important to me!", talker_id={1202}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="They gave out free fried fish balls today - you ate quite a few, Yuanya?", talker_id={1305}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="My stomach kinda hurts now...", talker_id={1202}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="Knew you overate meow~", talker_id={1205}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Everyone, just checked on Corrosicat.", talker_id={1301}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="How is she? Okay?", talker_id={1110}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="Artisan's adjusting her mechanical arm. As guessed - ate too many fish balls and feels sick.", talker_id={1301}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="Yuanya, if you're unwell, come get checked too.", talker_id={1301}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="...", talker_id={1202}, reward=0, relation={} },
		[23]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
		[10]={ talk_group={
		[1]={ next_id={2}, type=0, msg="@everyone", talker_id={1101}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Forwarding a notice", talker_id={1101}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="[Opinions on Leistance combat uniform style]", talker_id={1101}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Unified uniform? Cool.", talker_id={1208}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Since it's Leistance uniform,we should prioritize combat functionality. I suggest using Tutorial attire as a model.", talker_id={1101}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="Huh? Wouldn't Tutorial attire be a bit ugly?", talker_id={1207}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="I recommend traditional Vilatria clerical robes—excellent craftsmanship, and I happen to have plenty of fabric.", talker_id={1207}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="I prefer a knightly armor design. Both imposing and practical.", talker_id={1007}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="I disagree. Armor is too cumbersome.", talker_id={1004}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="In comparison, the Burksomi Military Academy's uniforms are much lighter.", talker_id={1004}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Will non-combat personnel also get uniforms?", talker_id={1307}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="Like dolls.", talker_id={1307}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="If possible, I'd like one for Zero too.", talker_id={1201}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="Why not incorporate ethnic patterns? Promi motifs, for example.", talker_id={1007}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="So… does anyone have a unified idea?", talker_id={1101}, reward=0, relation={} },
		[16]={ next_id={17}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=1, msg="Seems like no.", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Leistance's AIMBS members are all very strong-willed, huh.", talker_id={1110}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="No choice then…", talker_id={1101}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="I'll relay this feedback to HQ.", talker_id={1101}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="Meeting adjourned.", talker_id={1101}, reward=0, relation={} },
		[22]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
}
},
	[2004]={ type=2, hero_id={1109,1112,1206,1203,1305}, name="Secret Research Lab", talk_part={
		[1]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Alright, everyone's here now.", talker_id={1305}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Why am I here?", talker_id={1112}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="...", talker_id={1109}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Huh?", talker_id={1203}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Eh?", talker_id={1206}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="Let me explain—this is a cross-disciplinary research exchange group requested by higher-ups, so I added you all.", talker_id={1305}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="From now on, any research discussions, theoretical debates, or experimental collaborations within your fields can happen here.", talker_id={1305}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="If you need equipment or engineering support, you can also contact me.", talker_id={1305}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="If you need equipment or engineering support, you can also contact me.", talker_id={1305}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="It looks pretty good.", talker_id={1203}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="I'm responsible for plant research at Uzyanta. Um… any intel on mutated plants, feel free to share.", talker_id={1203}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="And if you, say, lose an arm or two during experiments, I can replace them with mechanical ones~", talker_id={1206}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Full-body replacements get a discount! Highly recommended—mechanical parts allow for more precision.", talker_id={1206}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="So? Interested in an upgrade?", talker_id={1206}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="I'll… pass for now. Thanks.", talker_id={1203}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="Aww, what a shame~", talker_id={1206}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="Me neither…", talker_id={1109}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="How about your Jellyfish?", talker_id={1206}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="…No.", talker_id={1109}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="You didn't even ask her! Sure you don't want to? I've never modified a Jellyfish before, but I can learn~", talker_id={1206}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="...", talker_id={1109}, reward=0, relation={} },
		[22]={ next_id={23}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=1, msg="Is this the world of scientists…?", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=0, msg="Anyway, I've got newly developed wasabi-and-chili-flavored energy drinks. Anyone want to test them?", talker_id={1112}, reward=0, relation={} },
		[25]={ next_id={26}, type=0, msg="Free shipping included.", talker_id={1112}, reward=0, relation={} },
		[26]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
		[2]={ talk_group={
		[1]={ next_id={2}, type=0, msg="@Catalpa Did you publish the paper [Impact of Water Environment Changes on Marine Plants]?", talker_id={1109}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Yes, I just finished it. You've read it?", talker_id={1203}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="Mm. I watched your lecture stream—well done.", talker_id={1109}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="But there's one part I don't quite follow. Or rather, I disagree.", talker_id={1109}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Which part? I'd like to hear your thoughts.", talker_id={1203}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="This is important to me.", talker_id={1203}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="Your research samples focus solely on Void Expanse freshwater systems. That's incomplete.", talker_id={1109}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Seawater participates in planetary hydrological cycles too—virtual particle contamination spreads during exchange.", talker_id={1109}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Pressure differentials in marine environments also create distinct issues. A freshwater-only conclusion is too absolute.", talker_id={1109}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="I see… I overlooked seawater variables.", talker_id={1203}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="I'll need time to revise the paper.", talker_id={1203}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="Thank you. I'll add your name as a contributor.", talker_id={1203}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="No need for the name—", talker_id={1109}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="Are you free now? I'd like to discuss this in person!", talker_id={1203}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="Eh… but I—", talker_id={1109}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="I've already scheduled a trip. I'll bring some edible mutated plants I cultivated—hope you like them!", talker_id={1203}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="I taste-tested them. They're safe!", talker_id={1203}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Does your Crystal Jellyfish eat?", talker_id={1203}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="...", talker_id={1109}, reward=0, relation={} },
		[20]={ next_id={21}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=1, msg="Probably not…?", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="The paper's deadline is tight too. Looking forward to meeting you!", talker_id={1203}, reward=0, relation={} },
		[23]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
		[3]={ talk_group={
		[1]={ next_id={2}, type=0, msg="[Link] Technology Development, over 990,000 vouchers distributed for free!", talker_id={1305}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Everyone, you should grab these coupons~", talker_id={1305}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="What is this?", talker_id={1112}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Research Engineering Association's material purchase coupons.", talker_id={1305}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Help yourself if you need anything.", talker_id={1305}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="Hmm... mostly manufacturing materials. No diving equipment?", talker_id={1109}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="Isn't diving equipment for sports? Let me check—I need to order new filtration materials.", talker_id={1112}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Last time my reagent got contaminated and blew up half the garage...", talker_id={1112}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="As long as I don't destroy the other half this time, I won't get scolded, right?", talker_id={1112}, reward=0, relation={} },
		[10]={ next_id={11}, type=2, msg="You'll DEFINITELY get scolded!", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=1, msg="I need to upgrade some temperature control devices.", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="The fruits I cultivated last time tasted like snot... so only I would eat them.", talker_id={1203}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Previously cultivated fruit tasted like snot, and nobody wanted to eat it except for me.", talker_id={1203}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="Wait, if not snot flavor, what was it supposed to taste like?", talker_id={1305}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="I imagined bug flavor. Must be the water filtration system's fault.", talker_id={1203}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="Anyway, needs troubleshooting.", talker_id={1203}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="...", talker_id={1305}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="@Artisan Want me to add your order? Group purchase discount available.", talker_id={1305}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="3 units of neural network materials. Sending specs shortly.", talker_id={1206}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="Got a new client requesting full-body replacement.", talker_id={1206}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="I'm getting excited~", talker_id={1206}, reward=0, relation={} },
