} },
		[4]={ talk_group={
		[1]={ next_id={2}, type=0, msg="My chemical research equipment got confiscated...", talker_id={1112}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="They said [to prevent you from blowing up the warehouse and starving next month.] Took ALL my tools.", talker_id={1112}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="So mad. Guess I'll research something else.", talker_id={1112}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="What did you do this time?", talker_id={1305}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="They refused to test-drink it, so I secretly added it to the boss's food.", talker_id={1112}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="His face turned green for days.", talker_id={1112}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="The color was quite pretty though~", talker_id={1112}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Now I see why your tools got taken.", talker_id={1305}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Want to try some? I saved a sample—tastes decent actually.", talker_id={1112}, reward=0, relation={} },
		[10]={ next_id={11}, type=2, msg="......", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=1, msg="……", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="I'm more interested in the pigment-altering compound.", talker_id={1203}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Could this induce color changes in plants?", talker_id={1203}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="I'd like to test that.", talker_id={1203}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="Haven't tried it on plants yet, but there are some samples left.", talker_id={1112}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="Can send it to you.", talker_id={1112}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="Thank you so much!", talker_id={1203}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Though I'd prefer you drink it yourself rather than feeding it to plants.", talker_id={1112}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="Anyway, if there are results, please let me know, I can continue improving here.", talker_id={1112}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="If there's a plant that can be used to make extract, please inform me.", talker_id={1112}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="I want to research some new flavors.", talker_id={1112}, reward=0, relation={} },
		[22]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
		[5]={ talk_group={
