		[4]={ next_id={5}, type=0, msg="You haven't opened it yet, right?", talker_id={1112}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Not yet.", talker_id={1203}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="Be careful when unboxing. Shipping vibrations may cause... changes.", talker_id={1112}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="...What changes?", talker_id={1203}, reward=0, relation={} },
