		[6]={ talk_group={
		[1]={ next_id={2}, type=0, msg="[Link] World Tech Expo opening at Lissugen Dream Pavilion on XX/XX", talker_id={1305}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Everyone, I received an exhibition invitation for this event.", talker_id={1305}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="Want to join me?", talker_id={1305}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="A tech exhibition? Not really interested...", talker_id={1109}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Hmm... If there's experimental prosthetic materials, maybe worth seeing.", talker_id={1206}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="My lab's having funding issues—still negotiating with higher-ups.", talker_id={1203}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="Probably can't attend.", talker_id={1203}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Mmm... Catalpa, want to enter the competition?", talker_id={1305}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Competition?", talker_id={1203}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="First prize gets one year of sponsor funding.", talker_id={1305}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Though profit/usage rights require coordination with organizers.", talker_id={1305}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="Are you interested, Catalpa?", talker_id={1305}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Let me think... Could work.", talker_id={1203}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="But I'm not sure what to present.", talker_id={1203}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="I've got an idea—", talker_id={1305}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="A compact marine ecosystem installation.", talker_id={1305}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="Ecosystem installation?", talker_id={1109}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="A self-contained miniature biome for urban landscaping.", talker_id={1305}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="I'll share the concept files later.", talker_id={1305}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="Hope you'll all consider collaborating!", talker_id={1305}, reward=0, relation={} },
		[21]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
		[7]={ talk_group={
		[1]={ next_id={2}, type=0, msg="[File attachment] Dream Tech Expo Proposal", talker_id={1305}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Posted my research and blueprints. Feedback welcome.", talker_id={1305}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="So it's miniature landscape design?", talker_id={1203}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Yes—replicating a marine biome segment.", talker_id={1305}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Urban applications seem most viable.", talker_id={1305}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="Ocean scenery in cities? Fun concept~", talker_id={1109}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="Hehe", talker_id={1305}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Since it crosses multiple specialties, I nominate Abyssal as project lead.", talker_id={1305}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Eh? Me?", talker_id={1109}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="Um... I...", talker_id={1109}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="No problem! You're perfect for it.", talker_id={1112}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="But...", talker_id={1109}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Decision made~ I'll handle materials, circuitry, and piping.", talker_id={1305}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="Clueless about biology, but engineering's my forte.", talker_id={1305}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="After revising my paper, I can manage the phytoscape.", talker_id={1203}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="An underwater forest would be spectacular.", talker_id={1203}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="I'll formulate the aquatic balancing agents.", talker_id={1112}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Then... I'll oversee the living organisms.", talker_id={1109}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="Need time to draft an eco-protocol.", talker_id={1109}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="Thanks for trusting me.", talker_id={1109}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="Just tell me what you need!", talker_id={1305}, reward=0, relation={} },
		[22]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
		[8]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Expo's over—great work everyone!", talker_id={1305}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="So many competitors...", talker_id={1305}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="Uh. Feels like a weight lifted.", talker_id={1203}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="I was terrified during the presentation.", talker_id={1203}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Huh? You seemed perfectly calm!", talker_id={1305}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="I... memorized the script all night.", talker_id={1203}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="Silver medal's fine—the sponsorship covers everything.", talker_id={1203}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Really, thank you all.", talker_id={1203}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Mission accomplished, no?", talker_id={1112}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="Sorry... My planning had gaps.", talker_id={1109}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="I should be thanking YOU.", talker_id={1203}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="Everyone worked so hard~", talker_id={1305}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Sponsors want to debut it at a new luxury hotel first.", talker_id={1305}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="They gave us discount coupons too.", talker_id={1305}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="Enough overthinking—let's celebrate!", talker_id={1305}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="Agreed.", talker_id={1112}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="I know a fantastic restaurant.", talker_id={1112}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Group outing it is!", talker_id={1305}, reward=0, relation={} },
		[19]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
		[9]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Got a special order recently.", talker_id={1206}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="A bit troubled.", talker_id={1206}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="Huh? Are there any weird request?", talker_id={1305}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Well... not exactly. More like something I've been waiting for.", talker_id={1206}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="A child's mother wants me to replace their entire body.", talker_id={1206}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="Replace their BODY?!", talker_id={1203}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="My specialty is prosthetics, exoskeletons, and modifications after all~", talker_id={1206}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="The kid's gravely ill—their body's falling apart. So tragic...", talker_id={1206}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Human bodies really are fragile.", talker_id={1206}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="Life is like that—decay and death are inevitable.", talker_id={1109}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Death is just another beginning.", talker_id={1109}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="Humans can be as fragile as plants sometimes.", talker_id={1203}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="True. That's why professions like ours exist—fear of mortality breeds demand.", talker_id={1206}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="Physical decay erodes the mind too.", talker_id={1206}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="Only machinery embodies eternal beauty. No more pain with mechanical bodies, right?", talker_id={1206}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="First time performing such major surgery... I'm thrilled!", talker_id={1206}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="Uh... so what's the actual problem?", talker_id={1305}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Ah right! Thanks for reminding me.", talker_id={1206}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="I need to upgrade my robotic arms for finer precision.", talker_id={1206}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="Free now? I'm coming over.", talker_id={1206}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="Yes!", talker_id={1305}, reward=0, relation={} },
		[22]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
		[10]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Tested the reagent on Little Bun.", talker_id={1203}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Results?", talker_id={1305}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="Did it turn green too?", talker_id={1305}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="Unexpected... developments occurred.", talker_id={1203}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="?", talker_id={1112}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="The fruits grew green filling. Texture resembles cake.", talker_id={1203}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="Weird.", talker_id={1203}, reward=0, relation={} },
		[8]={ next_id={9}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=1, msg="It actually greened?!", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="Bad cake flavor?", talker_id={1305}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="That wasn't cake to begin with...", talker_id={1112}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="Then something miraculous happened.", talker_id={1203}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Oh?", talker_id={1112}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="I saw tiny people dancing before my eyes.", talker_id={1203}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="THIS IS SERIOUS!", talker_id={1305}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="Go to the hospital!!", talker_id={1305}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="Relax—already consulted a doctor.", talker_id={1203}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Sigh What'd they say?", talker_id={1305}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="Busy dancing now. Results later.", talker_id={1203}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="You're lying down RIGHT NOW while I call a proper doctor!", talker_id={1305}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="Can I come too? Sounds fascinating.", talker_id={1112}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="First—HAND OVER THE REAGENT FORMULA!", talker_id={1305}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="Ehe~", talker_id={1112}, reward=0, relation={} },
		[24]={ next_id={0}, type=0, msg="[Gift Available]", talker_id={}, reward=13831, relation={} },
} },
