		[8]={ next_id={9}, type=0, msg="After all, I live in an ancient country where even sharing personal matters publicly is forbidden.", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=1, msg="That strict?", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="It's what they call [noble pride]—maintaining mystery, forbidding commoners from glimpsing aristocratic lives.", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="So, in my free time, I just scroll through Linker's social media feeds.", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Linker's updates... Life in Leistance is much more interesting than in Vilatria", talker_id={}, reward=0, relation={} },
