		[15]={ next_id={16,17}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[16]={ next_id={18}, type=1, msg="Does the Knight Order not have social media or the like?", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=1, msg="The Knights don't share their lives?", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="It's an age-old rule of the Order. Beyond work, no Stellar Knight is allowed to post about their private lives on public platforms.", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="Even private inquiries are forbidden, so outside of work, I hardly interact with anyone.", talker_id={}, reward=0, relation={} },
