		[4]={ talk_group={
		[1]={ next_id={2}, type=0, msg="1111", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=1, msg="1111", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=0, msg="[Smile].jpg", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Found an old book today and stayed up all night reading it. Feeling happy.", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=1, msg="What book?", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="The Death of a Star. It seems like astronomy, but it's actually about an astrologer chasing the star in his heart.", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="The stargazer spends his life pursuing that untouchable light.", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="At the end of his life, he finally sees himself clearly.", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="And like a dying star, he shines with one last brilliant glow.", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="To the universe, such light may be insignificant, but at least it existed—vividly, illuminating others.", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="It's hard to imagine such a story coming from a common writer...", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="Oh sorry, I don't mean there's anything wrong with common writers, just a bit surprised", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="In the old Vilatria, only nobles were educated and literate.", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="I can't help but wonder what kind of person could write such a story.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18,19}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[18]={ next_id={20}, type=1, msg="A moving story.", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=1, msg="Do you like stories like this?", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="Usually, I read more academic texts, like ancient star charts.", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="This book came to me by chance.", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="A commoner girl traded it for a divination session.", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="I didn't expect much, but the content surprised me. [Smile].jpg", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=1, msg="You do divinations for commoners too?", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=0, msg="Ah... well, that's because...", talker_id={}, reward=0, relation={} },
		[27]={ next_id={28}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[28]={ next_id={29}, type=1, msg="Because?", talker_id={}, reward=0, relation={} },
		[29]={ next_id={30}, type=0, msg="Because... I think I might be searching for my own star too.", talker_id={}, reward=0, relation={} },
		[30]={ next_id={31}, type=0, msg="And now, perhaps... I've already found it.", talker_id={}, reward=0, relation={} },
		[31]={ next_id={32}, type=0, msg="[Smile].jpg", talker_id={}, reward=0, relation={} },
		[32]={ next_id={33}, type=2, msg="", talker_id={}, reward=0, relation={} },
