		[34]={ next_id={35}, type=0, msg="The number you dialed cannot be reached at the moment. Please try again later. [System message]", talker_id={}, reward=0, relation={} },
		[35]={ next_id={36}, type=2, msg="", talker_id={}, reward=0, relation={} },
