		[7]={ next_id={8}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=1, msg="Did something happen?", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Well...", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="This is rather embarrassing to say... I wonder if you could keep it a secret for me.", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12,13}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[12]={ next_id={14}, type=1, msg="I promise to keep it secret.", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=1, msg="Don't force yourself if you're uncomfortable.", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="No, no, it's just... truly mortifying...", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="Do you remember that book I mentioned last time?", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=1, msg="I remember. You liked it so much you even posted about it.", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Yes, and that's where the problem lies.", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="I loved it so much that I tried reconstructing the star chart described in the book.", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="After spending some time on it...", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=1, msg="And then?", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="The astrolabe's star alignment formed a phrase, but it was in an ancient language.", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=0, msg="So I spent more time deciphering it...", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=1, msg="Did you manage to decode it?", talker_id={}, reward=0, relation={} },
		[27]={ next_id={28}, type=0, msg="Of course I did... but... well...", talker_id={}, reward=0, relation={} },
		[28]={ next_id={29}, type=0, msg="I didn't expect this result, though in hindsight, it makes sense...", talker_id={}, reward=0, relation={} },
		[29]={ next_id={30}, type=0, msg="It's both touching and sad.", talker_id={}, reward=0, relation={} },
		[30]={ next_id={31}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[31]={ next_id={32}, type=1, msg="Eh?", talker_id={}, reward=0, relation={} },
		[32]={ next_id={33}, type=0, msg="The book's star chart was actually a cipher using chapter titles. The decoded message was—", talker_id={}, reward=0, relation={} },
		[33]={ next_id={34}, type=0, msg="To the universe, a star's time may be insignificant, but I have already become part of it.", talker_id={}, reward=0, relation={} },
		[34]={ next_id={35}, type=0, msg="The cosmos is eternal and boundless, just as my love for you remains, frozen at the moment of time's end.", talker_id={}, reward=0, relation={} },
		[35]={ next_id={36}, type=0, msg="It's a love letter—written to someone, as vast and beautiful as the universe itself.", talker_id={}, reward=0, relation={} },
		[36]={ next_id={37}, type=0, msg="I copied the words onto parchment along with the star chart, intending to send it to you in an envelope... but—", talker_id={}, reward=0, relation={} },
		[37]={ next_id={38}, type=0, msg="By the Stars... I lost it.", talker_id={}, reward=0, relation={} },
		[38]={ next_id={39}, type=0, msg="To make such a careless mistake... is utterly shameful...", talker_id={}, reward=0, relation={} },
		[39]={ next_id={40}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[40]={ next_id={41}, type=1, msg="It's okay", talker_id={}, reward=0, relation={} },
