	[4510]={ type=1, hero_id={1017}, name="", talk_part={
		[1]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Little one, are you awake?", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Guess who I am~", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=1, msg="Only one person calls me [little one.]", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Oh? You guessed so quickly.", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="But this thing called a [wristband] is really convenient. Even across thousands of miles, we can talk instantly.", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=1, msg="Wristband? So you're in Leistance now?", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Mhm! Because little one said this place was important.", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="It might help me too.", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="So I came~", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="Though... there was a middle-aged man here who seemed to know I was coming.", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="He said he knows you, little one.", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=1, msg="Deputy Director Cyber?", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="That's what the others called him too.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="He said Leistance can help me.", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="But it'll take time.", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=1, msg="How long?", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="Maybe long, maybe short.", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="But at least it's good news, right?", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="Until then, little one, take good care of yourself.", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=0, msg="And wait for me obediently~", talker_id={}, reward=0, relation={} },
