		[28]={ next_id={0}, type=0, msg="～～～", talker_id={}, reward=0, relation={1017,200} },
} },
		[2]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Beep beep~ Little one, it's me.", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Right now, I'm on a really, really big... um... bird.", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=1, msg="Bird??", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Mhm! This bird has huge wings, and lots of people are sitting on them.", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=1, msg="Leistance's bird?", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="Exactly!", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=1, msg="You mean the Eternal Flame?", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Huh? Is that what you call it too?", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="That's what everyone calls it.", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="But I prefer calling it [bird].", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="Because... it flies in the sky.", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=1, msg="As long as you like it, let's just call it a bird.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="Hmm!", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="Too bad, I'm not a bird.", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="If I were,", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="I could fly to you and perch on your shoulder.", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=1, msg="I'd like you no matter what you are.", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="...Eh?", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=0, msg="Really?", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=0, msg="...", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=0, msg="I feel... a little strange.", talker_id={}, reward=0, relation={} },
		[27]={ next_id={28}, type=0, msg="My face is so hot.", talker_id={}, reward=0, relation={} },
		[28]={ next_id={0}, type=0, msg="I-I'll go now! Bye, little one!", talker_id={}, reward=0, relation={1017,200} },
} },
		[3]={ talk_group={
		[1]={ next_id={2}, type=0, msg="I made lots of plushies.", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Does little one want some?", talker_id={}, reward=0, relation={} },
