		[4]={ next_id={5}, type=1, msg="Can I?", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Of course.", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="Actually, many of them were made for you.", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="Guess what they look like?", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=1, msg="Like me.", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="...", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="W-Who told you?!", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=1, msg="Just a guess.", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="...", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="There are big ones and small ones.", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="By the way, I like the biggest one.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=1, msg="Why?", talker_id={}, reward=0, relation={} },
		[19]={ next_id={0}, type=0, msg="Because I can hug it while sleeping~", talker_id={}, reward=0, relation={1017,200} },
