		[4]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Little one,", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="today, inside the big bird,", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="I went to a place called the archives.", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=1, msg="What were you doing there?", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="I wanted to understand you better.", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=0, msg="So the deputy director told me", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=0, msg="the archives would be the best place.", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=1, msg="You were checking my records?", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="Is that not allowed?", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=1, msg="It's allowed, but there's nothing interesting there.", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="You're right.", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="It's all just dull words and pictures.", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="I've already seen these things... in little one's mind.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=1, msg="That sounds kinda weird...", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="Huh? Weird?", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="Really? But you also...", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=0, msg="...", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="Now that I think about it... maybe it is a little weird.", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="Mmm, the archives were useless anyway!", talker_id={}, reward=0, relation={} },
		[24]={ next_id={0}, type=0, msg="Seeing little one in person is much happier~", talker_id={}, reward=0, relation={1017,200} },
} },
		[5]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Beep beep~ Little one, it's me.", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Long time no see~ How long has it been since we last talked?", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[4]={ next_id={5}, type=1, msg="A month.", talker_id={}, reward=0, relation={} },
		[5]={ next_id={6}, type=0, msg="Wrong.", talker_id={}, reward=0, relation={} },
		[6]={ next_id={7}, type=0, msg="One month, ten days, and twenty minutes~", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=1, msg="You remember that clearly?", talker_id={}, reward=0, relation={} },
