		[10]={ next_id={11}, type=0, msg="I've kept careful count.", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=1, msg="I sent you lots of messages.", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="I saw them~", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="Sorry I couldn't reply right away.", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="I've been undergoing treatments with many doctors.", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="They said I can't go out often or contact you too much.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=1, msg="Then what's the difference from before? What are those people doing?", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=0, msg="Are you angry?", talker_id={}, reward=0, relation={} },
