		[21]={ next_id={22}, type=0, msg="Compared to my days in prison, I'm happy now.", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=0, msg="Though I'd be happier with you.", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="So I'm working hard to make that happen.", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=0, msg="Is little one doing the same?", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=1, msg="Yes. Though I don't know how.", talker_id={}, reward=0, relation={} },
		[27]={ next_id={28}, type=0, msg="Hehe, all you have to do... is wait for me.", talker_id={}, reward=0, relation={} },
		[28]={ next_id={0}, type=0, msg="Bye for now, little one.", talker_id={}, reward=1021, relation={} },
} },
