		[14]={ next_id={15}, type=0, msg="Wanna swap some out?", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=1, msg="People from Foden City sell stuff so boldly?", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="Nah nah, I'm no black-market dealer. Everything's legit.", talker_id={}, reward=0, relation={} },
