		[19]={ next_id={20}, type=1, msg="Not needed for now, thanks.", talker_id={}, reward=0, relation={} },
		[20]={ next_id={0}, type=0, msg="Alright~ Hit me up if you change your mind. Don't delete my contact!", talker_id={}, reward=0, relation={1018,200} },
} },
		[2]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Linker,", talker_id={}, reward=0, relation={} },
