		[15]={ next_id={16}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[16]={ next_id={0}, type=1, msg="Ah... I see...", talker_id={}, reward=0, relation={1018,200} },
} },
		[3]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Linker,", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="Your robots are acting up again today.", talker_id={}, reward=0, relation={} },
