		[17]={ next_id={18}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[18]={ next_id={0}, type=1, msg="...", talker_id={}, reward=0, relation={1018,200} },
} },
		[4]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Linker,", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="I lost a leg.", talker_id={}, reward=0, relation={} },
		[3]={ next_id={4}, type=0, msg="Think it's in your room?", talker_id={}, reward=0, relation={} },
