		[8]={ next_id={9}, type=0, msg="Also...", talker_id={}, reward=0, relation={} },
		[9]={ next_id={10}, type=0, msg="Bring back some crafting paper?", talker_id={}, reward=0, relation={} },
		[10]={ next_id={11}, type=0, msg="Want to make something.", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=1, msg="Sure.", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=1, msg="What for?", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=0, msg="Pressed flowers.", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=0, msg="I haven't done it for a long time, got the urge to make some since returning to Vilatria.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=0, msg="After finishing them, I'll bring them to the cemetery of the knights' squad to honor my fallen knight comrades,", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=0, msg="and my mentor, Knight Commander Danica.", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=1, msg="...I see. Will get it now.", talker_id={}, reward=0, relation={} },
		[21]={ next_id={22}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[22]={ next_id={23}, type=1, msg="Mind if I join the visit? Have things to say too.", talker_id={}, reward=0, relation={} },
		[23]={ next_id={24}, type=0, msg="Of course. Like what?", talker_id={}, reward=0, relation={} },
		[24]={ next_id={25}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[25]={ next_id={26}, type=1, msg="Want to tell Danica. You're now my sworn knight.", talker_id={}, reward=0, relation={} },
		[26]={ next_id={27}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[27]={ next_id={28}, type=1, msg="That you've found your path - she and the others may rest.", talker_id={}, reward=0, relation={} },
		[28]={ next_id={29}, type=0, msg="...Thank you, Linker.", talker_id={}, reward=0, relation={} },
		[29]={ next_id={0}, type=0, msg="Let's tell them together.", talker_id={}, reward=0, relation={1027,200} },
} },
		[2]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Linker.", talker_id={}, reward=0, relation={} },
