		[15]={ next_id={16}, type=0, msg="So this final one... is for our future.", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18}, type=1, msg="...I see.", talker_id={}, reward=0, relation={} },
		[18]={ next_id={19}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=1, msg="Then perhaps it needs a companion.", talker_id={}, reward=0, relation={} },
