} },
		[3]={ talk_group={
		[1]={ next_id={2}, type=0, msg="Linker.", talker_id={}, reward=0, relation={} },
		[2]={ next_id={3}, type=0, msg="When did you charm Tiya and Flicker?", talker_id={}, reward=0, relation={} },
