		[6]={ next_id={7}, type=1, msg="Charm who now?", talker_id={}, reward=0, relation={} },
		[7]={ next_id={8}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[8]={ next_id={9}, type=1, msg="Tiya's one thing - but Flicker? Impossible—", talker_id={}, reward=0, relation={} },
