		[10]={ next_id={11}, type=1, msg="...", talker_id={}, reward=0, relation={} },
		[11]={ next_id={12}, type=0, msg="...Quite blunt, dear Linker.", talker_id={}, reward=0, relation={} },
		[12]={ next_id={13}, type=0, msg="Saw exquisite gowns hidden in their quarters.", talker_id={}, reward=0, relation={} },
		[13]={ next_id={14}, type=0, msg="Tiya buying some makes sense - but Flicker?", talker_id={}, reward=0, relation={} },
		[14]={ next_id={15}, type=0, msg="Care to guess who she's dressing up for?", talker_id={}, reward=0, relation={} },
		[15]={ next_id={16}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[16]={ next_id={17}, type=1, msg="Probably formal wear for diplomatic banquets.", talker_id={}, reward=0, relation={} },
		[17]={ next_id={18,19}, type=2, msg="", talker_id={}, reward=0, relation={} },
		[18]={ next_id={20}, type=1, msg="We're here as Leistance envoys after all -", talker_id={}, reward=0, relation={} },
		[19]={ next_id={20}, type=1, msg="And they're heirs to Vilatria's great houses.", talker_id={}, reward=0, relation={} },
		[20]={ next_id={21}, type=0, msg="*Tch* Evasion doesn't suit you, Linker.", talker_id={}, reward=0, relation={} },
